const ACTIONS = {
  'portal.skill.execute': { method: 'POST' },
  'portal.skill.poll': { method: 'GET' },
  'portal.skill.presentation': { method: 'GET' }
};

const IMAGE_CAPABILITIES = new Set([
  'human_detect',
  'image_tagging',
